module tb_TopModule;
    logic       clk;
    logic       reset;
    logic [3:0] q;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        reset = 1;
        @(posedge clk);
        #1;
        if (q !== 4'd0) begin
            $display("SELFTEST FAIL: Reset state incorrect, q=%d", q);
            $finish;
        end

        reset = 0;
        for (int i = 0; i < 25; i++) begin
            int expected = i % 10;
            if (q !== expected[3:0]) begin
                $display("SELFTEST FAIL: At cycle %0d, expected %0d, got %0d", i, expected, q);
                $finish;
            end
            @(posedge clk);
            #1;
        end

        // Test synchronous reset during counting
        reset = 1;
        @(posedge clk);
        #1;
        if (q !== 4'd0) begin
            $display("SELFTEST FAIL: Synchronous reset failed, q=%d", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end

endmodule

